import fs from'node:fs';import{loadMHR}from'../teachers.mjs';const m=loadMHR(),zero=()=>({identity:Array(45).fill(0),pose:Array(204).fill(0),expression:Array(72).fill(0),correctives:true}),baseline=m.evaluate(zero()),rows=[];
const diff=(a,b)=>{let max=0,count=0;for(let i=0;i<a.length;i++){const d=Math.abs(a[i]-b[i]);max=Math.max(max,d);if(d>1e-6)count++;}return{max,count};};
for(const[group,n]of[['identity',45],['pose',204],['expression',72]])for(let i=0;i<n;i++){const s=zero(),lim=group==='pose'?m.meta.pose_limits[i]:null,locked=lim&&lim[0]===lim[1];let value=group==='identity'?.5:.2;if(lim){if(locked)value=lim[0];else value=lim[1]>0?Math.min(.2,lim[1]*.5):Math.max(-.2,lim[0]*.5);}s[group][i]=value;const q=m.evaluate(s),mesh=diff(q.vertices,baseline.vertices);let jointCount=0;for(let j=0;j<127;j++)if(q.joints.subarray(j*8,j*8+8).some((v,k)=>Math.abs(v-baseline.joints[j*8+k])>1e-7))jointCount++;rows.push({group,index:i,label:group==='pose'?m.meta.pose_names[i]:group==='expression'?m.meta.expression_names[i]:`identity_${i}`,locked:!!locked,value,maxVertexComponentDeltaMM:mesh.max*10,changedVertexCoordinates:mesh.count,changedJoints:jointCount,effect:locked?'locked':mesh.count?'mesh':jointCount?'joints-only':'no-observed-effect'});}
const out={sourceCommit:m.meta.commit,assetRelease:m.meta.asset_release,sampleMeaning:'One valid finite amplitude per native scalar; classify vertex and joint-state response separately. Not a common-mesh transfer test.',rows,summary:{mesh:rows.filter(r=>r.effect==='mesh').length,jointOnly:rows.filter(r=>r.effect==='joints-only').length,locked:rows.filter(r=>r.locked).length,noObservedEffect:rows.filter(r=>r.effect==='no-observed-effect').length}};fs.writeFileSync('research/mhr-native-effect-audit.json',JSON.stringify(out,null,2));console.log(out.summary);console.log(rows.filter(r=>r.effect==='joints-only'||r.effect==='no-observed-effect').map(r=>({label:r.label,effect:r.effect})))
